function fitDims(w,h,maxW,maxH){
  if(!(w>0)||!(h>0)||!(maxW>0)||!(maxH>0)) return null;
  var fw=maxW/w, fh=maxH/h, f=Math.min(fw,fh,1);
  return {w:Math.max(1,Math.round(w*f)), h:Math.max(1,Math.round(h*f))};
}
function pickFormat(fmt){
  if(fmt==='png') return {mime:'image/png',ext:'png'};
  if(fmt==='webp') return {mime:'image/webp',ext:'webp'};
  return {mime:'image/jpeg',ext:'jpg'};
}
var EXPORTS={fitDims:fitDims,pickFormat:pickFormat};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.ImageCompressForgePure = EXPORTS; }
